var ClearFormattingPlugin = class {
  id = "clear-formatting";
  label = "Clear Formatting";
  wb = null;
  init(ctx) {
    this.wb = ctx.workbook;
  }
  destroy() {
    this.wb = null;
  }
  items = [
    { type: "divisor" },
    {
      type: "i",
      content: "format_clear",
      tooltip: "Rimuovi formattazione",
      onclick: (_el, _obj, _item) => {
        const wb = this.wb;
        if (!wb)
          return;
        const sel = wb.getSelection();
        if (!sel)
          return;
        const { x1, y1, x2, y2 } = sel;
        for (let y = Math.min(y1, y2); y <= Math.max(y1, y2); y++) {
          for (let x = Math.min(x1, x2); x <= Math.max(x1, x2); x++) {
            const name = `${wb.getColumnName(x)}${y + 1}`;
            wb.resetStyle(name);
          }
        }
      }
    }
  ];
};

// src/app/toolbar-plugins/highlight-row.plugin.ts
var HighlightRowPlugin = class {
  id = "highlight-row";
  label = "Highlight Row";
  /** Colour used for the row highlight. Override before init() if desired. */
  highlightColor = "#fff3cd";
  wb = null;
  init(ctx) {
    this.wb = ctx.workbook;
  }
  destroy() {
    this.wb = null;
  }
  items = [
    { type: "divisor" },
    {
      type: "i",
      content: "border_color",
      tooltip: "Evidenzia riga",
      onclick: () => this._applyToRows({ "background-color": this.highlightColor })
    },
    {
      type: "i",
      content: "layers_clear",
      tooltip: "Rimuovi evidenziazione riga",
      onclick: () => this._applyToRows({ "background-color": "" })
    }
  ];
  _applyToRows(style) {
    const wb = this.wb;
    if (!wb)
      return;
    const sel = wb.getSelection();
    if (!sel)
      return;
    const colCount = wb.getColumnCount();
    const { y1, y2 } = sel;
    for (let y = Math.min(y1, y2); y <= Math.max(y1, y2); y++) {
      for (let x = 0; x < colCount; x++) {
        const name = `${wb.getColumnName(x)}${y + 1}`;
        wb.setCellStyle(name, style);
      }
    }
  }
};

